 2|
 3| static long long a[2000];
 4|
 5| int main() {
 6|   int n;
 7|   std::cin >> n;
 8|
 9|
10|   auto walk = [](auto &&self, int lo, int hi, auto &&leaf) -> long long {
11|     if (hi - lo == 1) return leaf(lo);
12|     const int mid = lo + (hi - lo) / 2;
13|     const long long left = self(self, lo, mid, leaf);
14|     return left + self(self, mid, hi, leaf);
15|   };
16|
17|   walk(walk, 0, n, [](int i) -> long long { std::cin >> a[i]; return 0; });
18|   const long long sum = walk(walk, 0, n, [](int i) { return a[i]; });
19|   const long long above =
20|       walk(walk, 0, n, [&](int i) -> long long { return a[i] * n > sum; });
